WITH order_stats AS (SELECT order_id, SUM(CASE WHEN method = 'cash' THEN amount ELSE 0 END) AS cash_amount, SUM(CASE WHEN status = 'REFUNDED' THEN amount ELSE 0 END) AS refunded_amount FROM payments GROUP BY order_id) SELECT o.customer_id, o.discount, os.cash_amount, os.refunded_amount FROM orders o INNER JOIN order_stats os ON o.id = os.order_id WHERE os.refunded_amount >= 51 ORDER BY o.discount DESC, os.cash_amount DESC;
